const EXPRESSIONS=[
{word:'yesterday',pt:'ontem',rule:'Sem preposição. Também: yesterday morning, yesterday afternoon, yesterday evening.',example:'I worked from home yesterday.',category:'Dia anterior'},
{word:'last night',pt:'ontem à noite',rule:'Use last night. Não use yesterday night.',example:'We watched a film last night.',category:'Noite anterior'},
{word:'last week / month / year',pt:'semana / mês / ano passado',rule:'Last vem antes do período, sem in, on ou at.',example:'She moved to London last year.',category:'Período anterior'},
{word:'two days ago',pt:'há dois dias',rule:'Ago vem depois da duração. Também: an hour ago, three weeks ago.',example:'He called me two days ago.',category:'Tempo decorrido'},
{word:'in 2020',pt:'em 2020',rule:'Use in com anos e meses: in 2019, in March. Acrescente o contexto de passado quando necessário.',example:'They opened the school in 2020.',category:'Ano ou mês'},
{word:'on Monday',pt:'na segunda-feira',rule:'Use on com dias e datas. Last Monday dispensa on.',example:'I saw her on Monday.',category:'Dia ou data'},
{word:'the day before yesterday',pt:'anteontem',rule:'Expressão fixa, sem uma preposição antes.',example:'We arrived the day before yesterday.',category:'Dois dias atrás'},
{word:'when I was a child',pt:'quando eu era criança',rule:'When apresenta o contexto no passado. Com I, use was.',example:'I played outside when I was a child.',category:'Fase da vida'},
{word:'at the weekend / on the weekend',pt:'no fim de semana',rule:'At the weekend é comum no Reino Unido; on the weekend, nos EUA. Last weekend dispensa preposição.',example:'We visited our friends last weekend.',category:'Variação de uso'}
];
